return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(((((n == 1)) && ((0 == 0))) || (((n == 0)) && ((((0 == 0)) == 0)))) ? 0 : (((n == 2)) && ((0 == 0))) ? 1 : 2);','language'=>'he_IL','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'מגבה את קובצי ומסד הנתונים של ה-WordPress שלך לאחסון משלך — Dropbox, Google Drive, Cloudflare R2, Amazon S3 או כל יעד תואם S3 — משחזר אותם בפעם אחת, ומייבא גיבויים שנוצרו על ידי תוספי גיבוי והעברה אחרים.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'גיבויים','Get Pro: schedules, several storages, encryption'=>'קבלת Pro: תזמונים, מגוון אמצעי אחסון, הצפנה','Working…'=>'בעבודה…','Finished'=>'הסתיים','Failed'=>'נכשל','Cancelled'=>'בוטל','Cancel'=>'ביטול','Restore'=>'שחזור','Delete'=>'מחק','Delete this backup from your storage? This cannot be undone.'=>'האם למחוק גיבוי זה מהאחסון שלך? לא ניתן לבטל פעולה זו.','No backups yet. Press “Back up now” to make the first one.'=>'אין עדיין גיבויים. יש ללחוץ על "גבה כעת" כדי ליצור את הראשון.','Reading your storage…'=>'קורא את נפח האחסון שלך…','a complete backup, as opposed to an incremental oneFull backup'=>'גיבוי מלא','a backup holding only what changed since an earlier oneIncremental backup'=>'גיבוי מצטבר','Encrypted'=>'מוצפן','From another site'=>'מאתר אחר','Database'=>'מסד נתונים','Files'=>'קבצים','Uploading %1$s: %2$s%%'=>'מעלה את %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'התחבר אל Dropbox בחלון שנפתח, ואז הדבק את הקוד ש-Dropbox מציג לך:','Saved.'=>'נשמר.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'האם להסיר את היעד הזה מהתוסף? הגיבויים המאוחסנים בו לא יימחקו.','Reload the page to see the restored site.'=>'יש לרענן את הדף כדי לראות את האתר ששוחזר.','Storage'=>'אחסון','Import & migrate'=>'ייבוא והעברה','Settings'=>'הגדרות','Sections'=>'מדורים','Google Drive is connected.'=>'Google Drive מחובר.','Google Drive could not be connected.'=>'לא ניתן היה להתחבר ל-Google Drive.','Details'=>'פרטים','Back up now'=>'גיבוי כעת','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'גיבויים נשמרים באחסון שלכם, לא בשרת הזה. <a href="%s">חברו את האחסון שלכם</a> תחילה.','What to back up'=>'מה לגבות','Files and database'=>'קבצים ומסד נתונים','Database only'=>'מסד נתונים בלבד','Files only'=>'קבצים בלבד','Note (optional)'=>'הערה (אופציונלי)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'כל חלק מועלה לאחסון שלך ומוסר משרת זה לפני יצירת החלק הבא, כך שהגיבוי לעולם אינו תופס מקום באחסון האתר שלך.','Your backups'=>'הגיבויים שלך','Refresh'=>'רענון','Restore this backup'=>'שחזור גיבוי זה','Passphrase'=>'ביטוי סיסמה','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'אני מבין שפעולה זו מחליפה את הקבצים ואת מסד הנתונים של אתר זה באלה של הגיבוי. קבצים שאינם נמצאים בגיבוי יישמרו.','Recent activity'=>'פעילות אחרונה','Backup'=>'גיבוי','Restore / import'=>'שחזור / ייבוא','Running'=>'פועל','Your storage'=>'אחסון' . "\0" . 'יעדי האחסון שלך' . "\0" . 'יעדי האחסון שלך','No storage yet. Choose where your backups go below.'=>'אין עדיין אחסון. בחר למטה לאן יישמרו הגיבויים שלך.','Ready'=>'מוכן','Not connected'=>'לא מחובר','Connect'=>'התחבר','Test'=>'בדיקה','Edit'=>'עריכה','Remove'=>'הסרה','Add storage'=>'הוספת שטח אחסון','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'גיבויים נשמרים ביעד אחסון אחד. כדי להשתמש ביעד אחר, ערוך או הסר את היעד שלמעלה.','Kind of storage'=>'סוג אחסון','Name (for you)'=>'שם (עבורך)','Provider'=>'ספק','Cloudflare account id'=>'מזהה חשבון Cloudflare','Endpoint address'=>'כתובת נקודת קצה','Region'=>'אזור','Bucket'=>'דלי','Access key id'=>'מזהה מפתח גישה','Secret access key'=>'מפתח גישה סודי','Leave empty to keep the saved key'=>'השאר ריק כדי לשמור על המפתח השמור','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'עבור Cloudflare R2: בלוח הבקרה של Cloudflare פתחו את R2, צרו באקט (bucket), לאחר מכן “Manage R2 API tokens” ← צרו טוקן עם הרשאות Object Read & Write עבור אותו באקט, והעתיקו לכאן את ה-access key id ואת ה-secret.','Dropbox app key'=>'מפתח אפליקציית Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'צור אפליקציה ב-dropbox.com/developers/apps (Scoped access, App folder) עם ההרשאות files.content.read, files.content.write ו-files.metadata.read, והעתק את ה-App key שלה לכאן. שמור, ולאחר מכן לחץ על Connect.','OAuth client id'=>'מזהה לקוח OAuth','OAuth client secret'=>'סוד לקוח OAuth','Leave empty to keep the saved secret'=>'השאר ריק כדי לשמור על הסוד השמור','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'ב-Google Cloud Console, הפעל את ה-Google Drive API, ולאחר מכן צור לקוח OAuth מסוג "Web application" עם כתובת זו כ-URI מורשה להפניה מחדש:','Save, then press Connect. The plugin only sees the files it creates.'=>'יש לשמור ולאחר מכן ללחוץ על התחברות. התוסף רואה רק את הקבצים שהוא יוצר.','Folder inside the storage (optional)'=>'תיקייה בתוך האחסון (אופציונלי)','Save storage'=>'חיסכון בשטח אחסון','Import a backup from another plugin or host'=>'ייבוא גיבוי מתוסף או מאחסון אחר','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'ייבא אתר מגיבוי שנוצר על ידי UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, או מכל ארכיון zip/tar של אתר WordPress עם קובץ ה-.sql שלו. התוכן מועבר אל wp-content ומסד הנתונים מחליף את זה של אתר זה; הכתובות משתנות לאלו של אתר זה באופן אוטומטי.','Upload from your computer'=>'העלאה מהמחשב שלך','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'יש לבחור את כל קובצי הגיבוי בבת אחת (UpdraftPlus יוצר כמה). קבצים גדולים נשלחים בחלקים קטנים, ולכן מגבלת ההעלאה של חברת האחסון שלך אינה חלה.','Or from links (Google Drive, Dropbox or any download address)'=>'או מקישורים (Google Drive, Dropbox או כל כתובת הורדה)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'קישור אחד בכל שורה. עבור Google Drive ו-Dropbox, שתף את הקובץ עם "כל מי שיש לו את הקישור" והדבק קישור זה; כבה שוב את השיתוף לאחר מכן.','Or a file already on this server'=>'או קובץ שכבר נמצא בשרת זה','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'יש להעלות ארכיונים באמצעות FTP או מנהל הקבצים של האחסון אל %s ולטעון מחדש עמוד זה.','Or a deploy code from another site'=>'או קוד פריסה מאתר אחר','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'אם אתר אחר סיפק לך קוד פריסה של Zinn® Backups, יש להדביק אותו כאן כדי להעתיק את הגיבוי לאתר זה מבלי לשתף את מפתחות האחסון שלו. הקוד תקף למשך מספר שעות; יש להתייחס אליו כאל סיסמה.','Passphrase (only if that backup is encrypted)'=>'ביטוי סיסמה (רק אם הגיבוי הזה מוצפן)','Import'=>'ייבוא','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'אני מבין שהייבוא מחליף את התוכן ומסד הנתונים של אתר זה. לאחר מכן, יש להתחבר באמצעות חשבון מהאתר המיובא.','Moving to Zinn® hosting?'=>'עוברים לאחסון של Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® יכול להעביר את האתר שלך מהאחסון הישן עבורך. אם האחסון הישן אינו מספק לך גישת FTP, SSH או לוח בקרה, התקן את Zinn® Migrate באתר הישן; הוא יוצר ארכיון יחיד שתוכל לייבא לכאן או להעביר אל Zinn®.','What goes into a backup'=>'מה נכלל בגיבוי','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'כלול את הקבצים של WordPress עצמה (wp-admin, wp-includes). בדרך כלל אין צורך: תמיד ניתן להתקין מחדש את WordPress.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'השמט גם את התיקיות או הקבצים האלה (אחד בכל שורה, יחסית לתיקיית WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'תמיד מוחרגים: מטמונים, שטח טיוטה לעדכונים ותיקיות הארכיון של תוספי גיבוי אחרים:','Size of each part (MB)'=>'גודל כל חלק (MB)','Save settings'=>'שמור הגדרות','A backup part could not be opened for writing. Check that wp-content has free space.'=>'לא ניתן היה לפתוח חלק מקובץ הגיבוי לכתיבה. יש לבדוק אם יש מקום פנוי ב-wp-content.','A backup part could not be written. Check that wp-content has free space.'=>'לא ניתן היה לכתוב חלק מגיבוי. יש לבדוק אם יש מקום פנוי ב-wp-content.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'תחילה יש לחבר יעד אחסון בלשונית Storage: הגיבויים נשמרים באחסון שלך, לא בשרת זה.','Multisite networks are not supported yet.'=>'רשתות מרובות אתרים עדיין אינן נתמכות.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'ב-PHP של שרת זה אין את הרחבת ZipArchive. בקש מחברת האחסון שלך להפעיל אותה.','Starting'=>'מתחיל','Listing files'=>'מציג רשימת קבצים','Backing up the database'=>'מגבה את מסד הנתונים','Packing files'=>'אורז קבצים','Uploading to your storage'=>'מעלה לאחסון שלך','Finishing'=>'מסיים','The backup reached an unknown stage.'=>'הגיבוי הגיע לשלב לא ידוע.','Backup %s started.'=>'הגיבוי של %s החל.','Found %1$s files (%2$s).'=>'נמצאו %1$s קבצים (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'מסד נתונים: %1$d טבלאות, %2$s שורות, %3$s מכווץ.','Backup complete: %1$s stored in %2$d destination.'=>'הגיבוי הושלם: %1$s נשמר ביעד %2$d.' . "\0" . 'הגיבוי הושלם: %1$s נשמר ב-%2$d יעדים.' . "\0" . 'הגיבוי הושלם: %1$s נשמר ב-%2$d יעדים.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'לא ניתן היה להסיר חלקים מסוימים שכבר הועלו מנפח האחסון שלך; הם נמצאים בתיקיית גיבוי לא שלמה ולעולם אינם מוצעים לשחזור.','A storage destination was removed while the backup was running.'=>'יעד אחסון הוסר בזמן שגיבוי פעל.','That is not a backup folder.'=>'זו אינה תיקיית גיבוי.','That storage destination is no longer saved on this site.'=>'יעד אחסון זה אינו שמור עוד באתר זה.','Later incremental backups are built on this one. Delete those first.'=>'גיבויים מצטברים מאוחרים יותר מבוססים על גיבוי זה. יש למחוק אותם קודם.','This file is not an encrypted Zinn® Backups file.'=>'קובץ זה אינו קובץ Zinn® Backups מוצפן.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'לא ניתן לפענח את הגיבוי: ביטוי הסיסמה שגוי או שהקובץ פגום.','The encrypted backup file is incomplete.'=>'קובץ הגיבוי המוצפן אינו שלם.','The database file could not be written. Check that wp-content has free space.'=>'לא ניתן היה לכתוב את קובץ מסד הנתונים. יש לבדוק שבתיקייה wp-content יש מקום פנוי.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'זה אינו קוד פריסה. קוד פריסה מתחיל ב-zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'קוד הפריסה הזה פגום. יש להעתיק אותו שוב מהאתר השני.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'תוקף קוד הפריסה פג או שהגיבוי שלו נמחק. צור קוד חדש באתר השני.','That deploy code does not point at a Zinn® Backups backup.'=>'קוד הפריסה הזה אינו מצביע על גיבוי של Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'תוקף קוד הפריסה פג. צור קוד חדש באתר השני.','The server stopped honouring partial downloads. Start the import again.'=>'השרת הפסיק לתמוך בהורדות חלקיות. יש להתחיל את הייבוא מחדש.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'הקישור פתח דף אינטרנט במקום קובץ. עבור Google Drive ו-Dropbox, שתף את הקובץ עם "כל מי שקיבל את הקישור" והדבק את הקישור הזה.','The link answered with HTTP %d.'=>'הקישור הגיב עם HTTP %d.','The file list could not be written.'=>'לא ניתן היה לכתוב את רשימת הקבצים.','The storage service could not be reached: %s'=>'לא הייתה אפשרות לגשת לשירות האחסון: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s השיב עם HTTP %2$d: %3$s','no details given'=>'לא סופקו פרטים','You are not allowed to manage backups.'=>'אין לך הרשאה לנהל גיבויים.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'סמן את התיבה כדי לאשר שהשחזור מחליף את הקבצים ומסד הנתונים של אתר זה.','Save the destination first.'=>'יש לשמור תחילה את היעד.','Connected: a test file was written and removed.'=>'מחובר: קובץ בדיקה נכתב והוסר.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'הזן תחילה את מפתח היישום של יישום ה-Dropbox שלך (ראה את השלבים לצד הטופס).','This kind of storage does not sign in.'=>'סוג אחסון זה אינו מתחבר.','The sign-in expired. Press Connect again.'=>'תוקף הכניסה פג. לחץ שוב על התחבר.','Dropbox is connected.'=>'Dropbox מחובר.','Settings saved.'=>'ההגדרות נשמרו.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'גיבוי, שחזור או ייבוא אחר פועל כעת. המתן לסיומו, או בטל אותו.','The upload was not started properly. Start again.'=>'ההעלאה לא התחילה כראוי. יש להתחיל שוב.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'המקטע לא הגיע. ייתכן שהשרת שלך מגביל את נפח ההעלאות; כדאי לנסות שוב.','Tick the box to confirm that the import replaces this site’s content and database.'=>'סמן את התיבה כדי לאשר שהייבוא מחליף את התוכן ואת מסד הנתונים של אתר זה.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'יש לבחור ארכיון לייבוא: להעלות אותו, להדביק קישור, או לבחור קובץ מתיקיית הייבוא.','Hosting customer? Get %1$d%% off %2$s'=>'לקוח אחסון? קבל %1$d%% הנחה על %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'כלקוח אחסון של Zinn Digital®, הינך מקבל קוד אישי של %d%% הנחה על התשלום הראשון שלך. החידושים הם במחיר הרגיל.','Get my %d%% code and go to checkout'=>'קבל את קוד ה-%d%% שלי ועבור לתשלום','Sorry, you are not allowed to do that.'=>'מצטערים, אין לך הרשאה לבצע פעולה זו.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'הנחה זו מיועדת ללקוחות בעלי תוכנית אחסון בתשלום במצב תקין. תקופות ניסיון בחינם אינן זכאיות.','You have already used your hosting-customer discount for this plugin.'=>'כבר השתמשת בהנחת לקוח האחסון שלך עבור תוסף זה.','We could not get your code just now. Please try again in a few minutes.'=>'לא הצלחנו לקבל את הקוד שלך כרגע. יש לנסות שוב בעוד מספר דקות.','Reading the backup'=>'קורא את הגיבוי','Downloading the archive'=>'הארכיון בהורדה','Recognising the archive'=>'מזהה את הארכיון','Restoring files'=>'משחזר קבצים','Downloading the database'=>'מוריד את מסד הנתונים','Restoring the database'=>'משחזר את מסד הנתונים','Updating the site address'=>'מעדכן את כתובת האתר','Switching to the restored database'=>'עובר למסד הנתונים ששוחזר','The restore reached an unknown stage.'=>'השחזור הגיע לשלב לא ידוע.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'תיקייה זו אינה מכילה גיבוי מלא של Zinn® Backups (המניפסט חסר).','This backup is encrypted. Enter its passphrase to restore it.'=>'גיבוי זה מוצפן. הזן את ביטוי הסיסמה שלו כדי לשחזר אותו.','This incremental backup needs backup %s, which is no longer in the storage.'=>'גיבוי מצטבר זה זקוק לגיבוי %s, שכבר אינו קיים באחסון.','Restoring the backup of %1$s (%2$d file parts).'=>'משחזר את הגיבוי של %1$s (%2$d חלקי קובץ).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'לא ניתן היה לדרוס את הקובץ %1$s מכיוון שאין לאתר זה הרשאה לשנות אותו, והוא הושאר כפי שהוא: %2$s' . "\0" . 'לא ניתן היה לשכתב %1$s קבצים מכיוון שלאתר זה אין הרשאה לשנות אותם, והם הושארו כפי שהם: %2$s' . "\0" . 'לא ניתן היה לשכתב %1$s קבצים מכיוון שלאתר זה אין הרשאה לשנות אותם, והם הושארו כפי שהם: %2$s','Restored %s files.'=>'שוחזרו %s קבצים.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s לא תאם לסיכום הביקורת שלו לאחר ההורדה. ייתכן שהעותק באחסון פגום.','%s did not arrive. Upload it again.'=>'הקובץ %s לא הגיע. נא להעלות אותו שוב.','Recognised: %s.'=>'זוהה: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'יובאו %1$s קבצים ל-wp-content (%2$s הושמטו: מטמונים, drop-ins ותיקיות של תוספי גיבוי אחרים).','The archive has no database dump, so only files were imported.'=>'הארכיון אינו מכיל גיבוי של מסד הנתונים, ולכן יובאו קבצים בלבד.','Database restored into %d temporary tables.'=>'מסד הנתונים שוחזר ל-%d טבלאות זמניות.','%s has no WordPress tables in it and was skipped.'=>'ב-%s אין טבלאות של WordPress והוא דולג.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'מסד הנתונים של הגיבוי אינו מכיל טבלאות WordPress, ולכן שום דבר לא הוחלף.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'גיבוי זה הוא של רשת אתרים (multisite). שחזור רשת לאתר בודד אינו נתמך.','Moving the content from %1$s to %2$s.'=>'מעביר את התוכן מ-%1$s אל %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'השחזור הושלם. אם נותקת, יש להתחבר באמצעות חשבון מהאתר ששוחזר.','Restore complete.'=>'השחזור הושלם.','%1$s — trying again in %2$d seconds.'=>'%1$s — מנסה שוב בעוד %2$d שניות.','Cancelled.'=>'בוטל.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'גיבויים נשמרים ביעד אחסון אחד. יש לערוך או להסיר את היעד הקיים כדי להשתמש ביעד אחר.','The database file could not be opened.'=>'לא ניתן היה לפתוח את קובץ מסד הנתונים.','The database refused a statement from the backup: %1$s (%2$s…)'=>'מסד הנתונים דחה פקודה מהגיבוי: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'לא ניתן היה להחליף את הטבלאות ששוחזרו: %s. האתר שלך נותר ללא שינוי.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'אין תיקייה עם הרשאות כתיבה עבור קובצי גיבוי זמניים. יש להגדיר הרשאות כתיבה עבור wp-content ולנסות שוב.','Could not create a folder for this job.'=>'לא ניתן היה ליצור תיקייה עבור משימה זו.','%s — guides and services'=>'%s — מדריכים ושירותים','User guides'=>'מדריכי משתמש','Read the %s user guide'=>'קרא את מדריך המשתמש של %s','Hide this'=>'הסתרת פריט זה','Zinn® hosting for WordPress'=>'אחסון Zinn® עבור WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, גיבויים יומיים, הגירה בחינם ולוח בקרה שנבנה עבור אנשים שמנהלים יותר מאתר אחד.','The Zinn® marketplace'=>'השוק של Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'קנו ומכרו אתרים קיימים, דומיינים ומיקומי קישורים, כאשר הכסף מוחזק בבטחה עד ששני הצדדים מרוצים.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — שכרו אנשים שמתפרנסים מכך','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'זירת הפרילנסרים הגלובלית שלנו: עיינו ביותר מ-10,000 שירותים מוכנים מאת כותבים, מעצבים, מפתחים ומומחי קידום אתרים, או פרסמו פרויקט ואפשרו להם להגיש הצעות מחיר.','See the Zinn Digital® release notes.'=>'הצג את הערות הגרסה של Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'שירות העדכונים של Zinn® לא סיפק קישור הורדה עבור עדכון זה. יש לבדוק אם אתר זה יכול לגשת לפלטפורמת Zinn®, ולאחר מכן לנסות שוב.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'לא ניתן היה להוריד את העדכון משירות העדכונים של Zinn® (%s). יש לנסות שוב בעוד מספר דקות.','The downloaded update failed its integrity check and was not installed.'=>'העדכון שהורד נכשל בבדיקת השלמות ולא הותקן.','The zip archive could not be opened. It may be damaged or incomplete.'=>'לא ניתן לפתוח את ארכיון ה-zip. ייתכן שהוא פגום או לא שלם.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'קובץ .wpress זה משתמש בפורמט שאיננו יכולים לקרוא (ייתכן שהוא מכווץ או מוצפן על ידי All-in-One WP Migration). אנא יצא אותו שוב ללא הצפנה.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'זהו קובץ “DupArchive” (.daf) של Duplicator. ב-Duplicator, צור את החבילה מחדש כאשר פורמט הארכיון מוגדר כ-ZIP, ואז ייבא אותה.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'גיבוי מסד הנתונים הזה של UpdraftPlus מוצפן. פתח את ההצפנה שלו ב-UpdraftPlus (או כבה את הצפנת מסד הנתונים ובצע גיבוי מחדש), ולאחר מכן יבא אותו.','Database dump'=>'דאמפ של מסד הנתונים','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s אינו ארכיון גיבוי שבאפשרותנו לקרוא (zip, tar, tar.gz, .wpress, .sql או .sql.gz).','Website archive'=>'ארכיון האתר','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'הקובץ %s אינו מכיל תוכן של WordPress (אין תיקיית wp-content ואין קובץ גיבוי של מסד הנתונים).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'קובץ .wpress זה מוצפן או מכווץ על ידי All-in-One WP Migration. אנא ייצאו אותו שוב כאשר ההצפנה והכיווץ כבויים, ולאחר מכן ייבאו אותו.','Other S3-compatible storage'=>'אחסון אחר תואם S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 או תואם S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'לא ניתן היה לקרוא את מפתחות האחסון באתר זה. יש להזין שוב את המפתח הסודי בלשונית אחסון.','This kind of storage is not known.'=>'סוג אחסון זה אינו מוכר.','Choose a kind of storage.'=>'יש לבחור סוג אחסון.','Enter the bucket name and the access key.'=>'הזן את שם ה-bucket ומפתח הגישה.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'הזן את מזהה חשבון ה-Cloudflare שלך (או את נקודת הקצה המלאה של R2).','Enter the endpoint address of your storage.'=>'הזן את כתובת נקודת הקצה של האחסון שלך.','Enter the OAuth client id from your Google Cloud project.'=>'הזן את ה-OAuth client id מפרויקט ה-Google Cloud שלך.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox לא החזיר אסימון רענון. יש להתחיל את החיבור מחדש.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox אינו מחובר. יש לחבר אותו שוב בלשונית אחסון.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google לא החזיר אסימון רענון. הסר אתר זה מגישת צד שלישי בחשבון Google שלך והתחבר שוב.','That file is not in Google Drive any more.'=>'הקובץ הזה כבר לא נמצא ב-Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive אינו מחובר. יש לחבר אותו שוב בלשונית אחסון.','The storage service did not start the upload.'=>'שירות האחסון לא התחיל את ההעלאה.','The storage service sent a reply that could not be read.'=>'שירות האחסון שלח תגובה שלא ניתן היה לקרוא.','A temporary backup file could not be read.'=>'לא ניתן היה לקרוא קובץ גיבוי זמני.','A deploy link is read-only.'=>'קישור פריסה הוא לקריאה בלבד.','The deploy code has no link for a file this backup needs.'=>'לקוד הפריסה אין קישור לקובץ שלו גיבוי זה זקוק.','The deploy link'=>'קישור הפריסה']];